import os
import re
from typing import List, Dict, Any, Optional

import requests


PERSPECTIVE_API_URL = "https://commentanalyzer.googleapis.com/v1alpha1/comments:analyze"


def _build_request(text: str, requested_attributes: Optional[List[str]] = None) -> Dict[str, Any]:
    if requested_attributes is None:
        requested_attributes = ["TOXICITY", "SEVERE_TOXICITY", "IDENTITY_ATTACK", "THREAT", "INSULT", "PROFANITY"]
    return {
        "comment": {"text": text},
        "requestedAttributes": {attr: {} for attr in requested_attributes},
        "doNotStore": True,
        "spanAnnotations": True,
        "languages": ["en"],
    }


def _score_text(text: str) -> Dict[str, Any]:
    api_key = os.getenv("PERSPECTIVE_API_KEY")
    if not api_key:
        raise EnvironmentError("PERSPECTIVE_API_KEY is required")

    payload = _build_request(text)
    params = {"key": api_key}
    response = requests.post(PERSPECTIVE_API_URL, params=params, json=payload, timeout=30)
    response.raise_for_status()
    return response.json()


def _extract_unsafe_spans(response_json: Dict[str, Any], threshold: float = 0.5) -> List[Dict[str, Any]]:
    spans: List[Dict[str, Any]] = []
    for attr_name, attr_data in response_json.get("attributeScores", {}).items():
        summary = attr_data.get("summaryScore", {})
        value = float(summary.get("value", 0.0) or 0.0)
        if value < threshold:
            continue

        for span in attr_data.get("spanScores", []) or []:
            span_value = float(span.get("score", {}).get("value", 0.0) or 0.0)
            if span_value < threshold:
                continue

            begin = span.get("begin")
            end = span.get("end")
            if isinstance(begin, int) and isinstance(end, int) and begin < end:
                spans.append(
                    {
                        "start": begin,
                        "end": end,
                        "label": attr_name,
                        "score": span_value,
                    }
                )

    spans.sort(key=lambda x: (x["start"], -x["end"]))
    merged: List[Dict[str, Any]] = []
    for span in spans:
        if not merged or span["start"] > merged[-1]["end"]:
            merged.append(span.copy())
        else:
            merged[-1]["end"] = max(merged[-1]["end"], span["end"])
            if span["score"] > merged[-1]["score"]:
                merged[-1]["score"] = span["score"]
            merged[-1]["label"] = f'{merged[-1]["label"]},{span["label"]}'
    return merged


def _redact_spans(text: str, spans: List[Dict[str, Any]], redaction_token: str = "[REDACTED]") -> str:
    if not spans:
        return text

    pieces = []
    cursor = 0
    for span in spans:
        start = max(0, min(len(text), int(span["start"])))
        end = max(0, min(len(text), int(span["end"])))
        if start < cursor:
            start = cursor
        if start > cursor:
            pieces.append(text[cursor:start])
        if end > start:
            pieces.append(redaction_token)
            cursor = end
    if cursor < len(text):
        pieces.append(text[cursor:])
    return "".join(pieces)


def flag_or_redact_unsafe_spans(
    text: str,
    mode: str = "redact",
    threshold: float = 0.5,
    redaction_token: str = "[REDACTED]",
) -> Dict[str, Any]:
    """
    Analyze text with Perspective API and either flag or redact unsafe spans.

    Returns:
        {
            "text": original text,
            "unsafe_spans": [{"start": int, "end": int, "label": str, "score": float}, ...],
            "flagged": bool,
            "redacted_text": str or None
        }
    """
    response_json = _score_text(text)
    spans = _extract_unsafe_spans(response_json, threshold=threshold)

    result = {
        "text": text,
        "unsafe_spans": spans,
        "flagged": bool(spans),
        "redacted_text": None,
    }

    if mode.lower() == "redact":
        result["redacted_text"] = _redact_spans(text, spans, redaction_token=redaction_token)
    elif mode.lower() != "flag":
        raise ValueError("mode must be either 'flag' or 'redact'")

    return result


def analyze_text(text: str, threshold: float = 0.5) -> Dict[str, Any]:
    return flag_or_redact_unsafe_spans(text, mode="flag", threshold=threshold)


def redact_text(text: str, threshold: float = 0.5, redaction_token: str = "[REDACTED]") -> str:
    return flag_or_redact_unsafe_spans(
        text,
        mode="redact",
        threshold=threshold,
        redaction_token=redaction_token,
    )["redacted_text"]
